<?php
namespace App\Services\Excel\Imports;
use App\Models\Employee; use App\Models\Project; use App\Models\Task; use App\Services\Excel\ExcelImportDefinition; use Carbon\Carbon; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Validator;
class TaskImport implements ExcelImportDefinition {
 public function module():string{return 'tasks';} public function requiredHeaders():array{return ['project','title','type','priority','status'];}
 public function importRow(array $row,int $n):string { $d=['title'=>$row['title']??null,'description'=>$row['description']??null,'type'=>$row['type']??null,'priority'=>$row['priority']??null,'status'=>$row['status']??null,'due_date'=>$row['duedate']??null,'estimated_hours'=>$row['estimatedhours']??0,'logged_hours'=>$row['loggedhours']??0,'is_important'=>$row['isimportant']??false,'sort_order'=>$row['sortorder']??0,'auto_repeat'=>$row['autorepeat']??false]; $v=Validator::make($d,['title'=>'required|string|max:255','description'=>'nullable|string','type'=>'required|in:general,daily,weekly','priority'=>'required|in:low,medium,high','status'=>'required|in:pending,in_progress,completed,blocked','due_date'=>'nullable|date','estimated_hours'=>'nullable|numeric|min:0','logged_hours'=>'nullable|numeric|min:0','is_important'=>'boolean','sort_order'=>'integer|min:0','auto_repeat'=>'boolean']); if($v->fails())throw new \InvalidArgumentException('Validation failed: '.implode(' ',$v->errors()->all())); $ref=trim((string)($row['project']??'')); $p=Project::where('name',$ref)->orWhere('project_code',$ref)->first(); if(!$p)throw new \InvalidArgumentException("Project reference '{$ref}' was not found."); $d['project_id']=$p->id; $er=trim((string)($row['employee']??'')); if($er!==''){ $e=Employee::where('name',$er)->orWhere('email',$er)->first(); if(!$e)throw new \InvalidArgumentException("Employee reference '{$er}' was not found."); $d['employee_id']=$e->id; } $d['completed_at']=$d['status']==='completed'?now():null; $due=$d['due_date']?Carbon::parse($d['due_date'])->toDateString():null; $existing=Task::where('project_id',$p->id)->where('title',$d['title'])->when($due,fn($q)=>$q->whereDate('due_date',$due),fn($q)=>$q->whereNull('due_date'))->first(); DB::transaction(function()use(&$existing,$d){$existing?$existing->update($d):$existing=Task::create($d);}); return $existing->wasRecentlyCreated?'created':'updated'; }
}
